using TownOfHost;
class Program{
static int passed;static PlayerControl host,other;
static void Check(bool ok,string s){if(!ok)throw new Exception(s);}static void Reset(){host=new(){PlayerId=0,AmOwner=true,NetId=100};other=new(){PlayerId=4,NetId=104};PlayerControl.LocalPlayer=host;PlayerCatch.Players=new(){{0,host},{4,other}};AmongUsClient.Instance=new();DebugModeManager.AmDebugger=false;DebugModeManager.EnableDebugMode=new();DebugModeManager.EnableTOHhmDebugMode=new();HudManager.Instance=new();ChatCommands.ReachedNormal=false;Logger.Messages.Clear();RPC.Syncs=NameColorManager.Removals=0;GameStates.InGame=true;PlayerState.State=new();}
static void Test(string n,Action a){Reset();a();passed++;Console.WriteLine("PASS "+n);}static void Authorize(){DebugModeManager.AmDebugger=true;DebugModeManager.EnableDebugMode.Value=DebugModeManager.EnableTOHhmDebugMode.Value=true;}
static void Main(){
for(int bits=0;bits<32;bits++){int x=bits;Test("permission conjunction "+x,()=>{bool a=(x&1)!=0,b=(x&2)!=0,c=(x&4)!=0,d=(x&8)!=0,e=(x&16)!=0;Check(DevelopmentCommandPolicy.CanUseHostDevelopmentCommand(a,b,c,d,e)==(x==31),"permission bypass");});}
foreach(var text in new[]{"/002","/cmd 002","/cmd /002"," /CMD\t002 ","/rev","/revive","/cmd rev","/cmd /revive 4","/cmd cr Tuner 4","/debug rev 4","/cmd dgm","/cmd FPS","/cmd wiop Tuner"}){string input=text;Test("restricted input classification",()=>Check(DevelopmentCommandPolicy.TryGetRestrictedCommand(input,out _),"not classified"));}
foreach(var text in new[]{"hello /cmd rev","/cmd candy 2","/cmd candy 1","/cmd tp o","/cmd wi","/cmd h","/cmd co Crewmate","/cmd co Tuner","/cmd","/revival","/cmdr rev"}){string input=text;Test("ordinary/role command preserved",()=>Check(!DevelopmentCommandPolicy.TryGetRestrictedCommand(input,out _),"ordinary command blocked"));}
Test("release default host cannot revive even with local input",()=>{ChatCommands.ExecuteReviveCommand(host,new[]{"/rev","4"},true);Check(other.Revives==0&&RPC.Syncs==0,"release escalation");});
Test("debug option alone cannot grant developer rights",()=>{DebugModeManager.EnableDebugMode.Value=DebugModeManager.EnableTOHhmDebugMode.Value=true;ChatCommands.ExecuteReviveCommand(other,new[]{"/rev","4"},true);ChatCommands.ExecuteInGameRoleChange(other,new[]{"/cr","Tuner","4"},true);Check(other.Revives+other.RoleChanges+RPC.Syncs==0,"shared flag grants remote rights");});
Test("authorized local host explicit revive works",()=>{Authorize();ChatCommands.ExecuteReviveCommand(host,new[]{"/rev","4"},true);Check(other.Revives==1&&RPC.Syncs==1,"authorized local revive failed");});
Test("authorized local host explicit role change works",()=>{Authorize();ChatCommands.ExecuteInGameRoleChange(host,new[]{"/cr","Tuner","4"},true);Check(other.RoleChanges==1&&RPC.Syncs==1&&NameColorManager.Removals==1,"authorized local change failed");});
Test("received handler defaults deny even forged local host",()=>{Authorize();ChatCommands.ExecuteReviveCommand(host,new[]{"/rev","4"});ChatCommands.ExecuteInGameRoleChange(host,new[]{"/cr","Tuner","4"});Check(other.Revives+other.RoleChanges+RPC.Syncs==0,"claimed host escaped origin gate");});
Test("non-host cannot acquire rights with owner flag and local input",()=>{Authorize();AmongUsClient.Instance.AmHost=false;ChatCommands.ExecuteReviveCommand(host,new[]{"/rev","4"},true);Check(other.Revives==0,"nonhost escalation");});
Test("other PlayerControl cannot acquire rights by AmOwner alone",()=>{Authorize();other.AmOwner=true;Check(!ChatCommands.CanUseReviveCommand(other,true)&&!ChatCommands.CanUseChangeRoleCommand(other,true),"spoofed owner");});
Test("missing and disconnected host fail closed",()=>{Authorize();Check(!ChatCommands.CanUseReviveCommand(null,true),"null sender");host.Data.Disconnected=true;Check(!ChatCommands.CanUseReviveCommand(host,true),"disconnected host");host.Data=null;Check(!ChatCommands.CanUseReviveCommand(host,true),"missing data");AmongUsClient.Instance=null;Check(!ChatCommands.CanUseReviveCommand(host,true),"missing client");});
Test("revive and role-change need their own enabled options",()=>{Authorize();DebugModeManager.EnableDebugMode.Value=false;Check(!ChatCommands.CanUseReviveCommand(host,true)&&ChatCommands.CanUseChangeRoleCommand(host,true),"wrong option");DebugModeManager.EnableTOHhmDebugMode=null;Check(!ChatCommands.CanUseChangeRoleCommand(host,true),"null option");});
foreach(var command in new[]{"/002","/cmd 002","/cmd rev 4","/cmd cr Tuner 4","/cmd debug rev 4","/cmd dgm","/cmd fps","/cmd wiop Tuner"}){string input=command;Test("received command always denied despite host identity",()=>{Authorize();ChatCommands.ReceivedGate(host,input,out bool canceled,true);Check(canceled&&!ChatCommands.ReachedNormal&&other.Revives+other.RoleChanges+RPC.Syncs==0,"RPC host impersonation");});}
Test("normal received role command reaches existing pipeline",()=>{ChatCommands.ReceivedGate(other,"/cmd candy 1",out bool canceled);Check(!canceled&&ChatCommands.ReachedNormal,"role pipeline changed");});
foreach(var input in new[]{"/002","/cmd 002","/cmd /002"}){string text=input;Test("002 consumed locally with no network or identity logging",()=>{Authorize();var chat=new ChatController();chat.freeChatField.textArea.text=text;Check(!ChatCommands.LocalGate(chat)&&chat.freeChatField.textArea.text=="","not consumed");Check(AmongUsClient.Instance.Sent==0&&Logger.Messages.Count==0&&HudManager.Instance.Chat.Texts.Count==1,"identity export side effects");});}
Test("non-host cmdless admin input is consumed before forwarding",()=>{AmongUsClient.Instance.AmHost=false;var chat=new ChatController();chat.freeChatField.textArea.text="/rev 4";Check(ChatCommands.TrySendCmdlessCommandDirectly(chat)&&AmongUsClient.Instance.Sent==0&&chat.freeChatField.textArea.text=="","forwarded admin command");});
Test("forwarding helper independently blocks admin commands",()=>{AmongUsClient.Instance.AmHost=false;foreach(var text in new[]{"/cmd rev 4","/002","/cmd cr Tuner 4"})ChatCommands.RequestCommandProcessingFromHost(text);Check(AmongUsClient.Instance.Sent==0,"forwarder bypass");});
Test("forwarding helper preserves ordinary role command RPC",()=>{AmongUsClient.Instance.AmHost=false;ChatCommands.RequestCommandProcessingFromHost("/cmd candy 1");Check(AmongUsClient.Instance.Sent==1,"ordinary RPC blocked");});
Test("authorized host local UI gate continues without notice",()=>{Authorize();var chat=new ChatController();chat.freeChatField.textArea.text="/cmd rev 4";Check(ChatCommands.LocalGate(chat)&&HudManager.Instance.Chat.Texts.Count==0,"authorized UI blocked");});
Console.WriteLine($"RESULT {passed} passed, 0 failed");}}
